package org.sleepwell.app;

import android.app.Activity;
import android.content.SharedPreferences;
import android.os.Bundle;
import android.view.*;
import android.view.accessibility.AccessibilityNodeInfo;
import android.widget.*;
import java.util.*;

/** One silent draft. Row taps select; only Use changes the current mix and timer. */
final class SleepMixerChoiceEditor {
    private static final int INK=0xfff7efff,MUTED=0xffd0bce9,PANEL=0xff4b3e60;
    private final Activity activity;private final Runnable finished;private final SharedPreferences preferences;
    private SoundMix previous;private String kind,error="";private long revision;private int value;
    private ScrollView scroll;private int scrollY;private String focusedControl="";private boolean accessibilityFocus;private final Map<String,View> focusTargets=new LinkedHashMap<>();
    private final Map<Integer,ChoiceRow> rows=new LinkedHashMap<>();private Button use;private TextView clamp,errorView;
    SleepMixerChoiceEditor(Activity activity,String kind,Bundle state,Runnable finished){this.activity=activity;this.finished=finished;preferences=SoundPreferences.factory.open(activity);this.kind=kind;try{previous=SoundPreferences.load(preferences).copy();revision=SoundPreferences.revision(preferences);if(!Set.of("timer","fade").contains(kind))throw new IllegalArgumentException();value=kind.equals("timer")?previous.timerMinutes:previous.fadeMinutes;if(state!=null){this.kind=state.getString("kind",kind);revision=state.getLong("revision",revision);value=state.getInt("value",value);error=state.getString("error","");scrollY=Math.max(0,state.getInt("scroll",0));focusedControl=state.getString("focusedControl","");accessibilityFocus=state.getBoolean("accessibilityFocus",false);if(!this.kind.equals(kind)||value<(kind.equals("timer")?1:0)||value>(kind.equals("timer")?240:previous.timerMinutes))throw new IllegalArgumentException();}}catch(RuntimeException invalid){previous=null;error="The mix changed or could not be read. Cancel and reopen this setting.";}}
    Bundle state(){rememberUi();Bundle out=new Bundle();out.putString("kind",kind);out.putInt("value",value);out.putLong("revision",revision);out.putString("error",error);out.putInt("scroll",scrollY);out.putString("focusedControl",focusedControl);out.putBoolean("accessibilityFocus",accessibilityFocus);return out;}
    void render(){rememberUi();rows.clear();focusTargets.clear();LinearLayout body=Design.darkPage(activity);scroll=(ScrollView)body.getParent();scroll.setContentDescription(kind.equals("timer")?"Sound timer choices":"Sound fade choices");RecordUi.label(activity,body);LinearLayout header=Design.row(activity);Design.Icon back=(Design.Icon)Design.iconButton(activity,"back","Cancel "+kind,finished);back.tint(INK);focusTargets.put("back",back);header.addView(back,new LinearLayout.LayoutParams(dp(48),dp(48)));header.addView(Design.text(activity,kind.equals("timer")?"Sound timer":"Fade out",25,600,INK),new LinearLayout.LayoutParams(0,-2,1));body.addView(header);Design.space(body,16);
        Design.text(body,kind.equals("timer")?"Stop after this much playing time. Pause freezes the timer.":"Lower the mix level during the final part of its timer.",14,400,MUTED);Design.space(body,16);
        if(previous==null){Design.text(body,error,14,500,Design.LILAC);focusTargets.put("cancel",SleepMixerUi.button(RecordUi.footer(body),"Cancel",false,finished));restoreUi();return;}
        SortedSet<Integer> values=new TreeSet<>();for(int n:kind.equals("timer")?new int[]{15,30,45,60,90,120,240}:new int[]{0,1,2,5,10,15})if(kind.equals("timer")||n<=previous.timerMinutes)values.add(n);values.add(kind.equals("timer")?previous.timerMinutes:previous.fadeMinutes);values.add(value);
        for(int n:values){LinearLayout row=Design.row(activity);Design.pad(row,14,8);row.setMinimumHeight(dp(56));Design.Icon indicator=new Design.Icon(activity,"check",Design.LILAC);row.addView(indicator,new LinearLayout.LayoutParams(dp(24),dp(24)));TextView label=Design.text(activity,n==0?"Off":n+" min",16,400,INK);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.leftMargin=dp(14);row.addView(label,lp);row.setFocusable(true);row.setContentDescription(n==0?"Off":n+" minutes");rows.put(n,new ChoiceRow(row,indicator,label));focusTargets.put("choice:"+n,row);row.setOnClickListener(v->{if(value==n)return;InteractionFeedback.selection(v);value=n;error="";refreshChoices();});body.addView(row);Design.space(body,4);}
        Design.space(body,12);clamp=Design.text(body,"",13,500,MUTED);Design.text(body,"Updates the saved mix and current playback.",12,400,MUTED);errorView=Design.text(body,"",13,500,Design.LILAC);LinearLayout footer=RecordUi.footer(body);use=SleepMixerUi.button(footer,"",true,this::save);focusTargets.put("use",use);focusTargets.put("cancel",SleepMixerUi.button(footer,"Cancel",false,finished));refreshChoices();restoreUi();
    }
    private void refreshChoices(){for(Map.Entry<Integer,ChoiceRow> entry:rows.entrySet()){ChoiceRow choice=entry.getValue();boolean selected=value==entry.getKey();choice.row.setBackground(Design.touch(activity,selected?PANEL:android.graphics.Color.TRANSPARENT,14));choice.indicator.setVisibility(selected?View.VISIBLE:View.INVISIBLE);choice.label.setTypeface(Design.font(activity,selected?600:400));SleepPicker.radio(choice.row,selected);}use.setText(kind.equals("timer")?"Use "+value+" min timer":value==0?"Use no fade":"Use "+value+" min fade");boolean shortens=kind.equals("timer")&&previous.fadeMinutes>value;clamp.setText(shortens?"The existing fade will shorten to "+value+" min.":"");clamp.setVisibility(shortens?View.VISIBLE:View.GONE);errorView.setText(error);errorView.setVisibility(error.isEmpty()?View.GONE:View.VISIBLE);}
    private void rememberUi(){if(scroll==null||!scroll.isAttachedToWindow())return;scrollY=scroll.getScrollY();focusedControl="";accessibilityFocus=false;for(Map.Entry<String,View> entry:focusTargets.entrySet()){View target=entry.getValue();if(target.hasFocus()||target.isAccessibilityFocused()){focusedControl=entry.getKey();accessibilityFocus=target.isAccessibilityFocused();break;}}}
    private void restoreUi(){ScrollView owner=scroll;owner.post(()->{if(activity.isDestroyed()||scroll!=owner||!owner.isAttachedToWindow())return;owner.scrollTo(0,scrollY);View target=focusTargets.get(focusedControl);if(target!=null){if(accessibilityFocus)target.performAccessibilityAction(AccessibilityNodeInfo.ACTION_ACCESSIBILITY_FOCUS,null);else target.requestFocus();}});}
    private static final class ChoiceRow {final LinearLayout row;final View indicator;final TextView label;ChoiceRow(LinearLayout row,View indicator,TextView label){this.row=row;this.indicator=indicator;this.label=label;}}
    private int dp(int n){return Design.dp(activity,n);}
    private void save(){if(previous==null)return;try{SoundMix next=previous.copy();if(kind.equals("timer")){next.timerMinutes=value;next.fadeMinutes=Math.min(next.fadeMinutes,value);}else next.fadeMinutes=value;next.validate();if(!SoundPreferences.saveIfRevision(preferences,revision,next))throw new IllegalStateException("The mix changed while this choice was open. Cancel and reopen it before saving.");SleepSoundService.update(activity);finished.run();}catch(RuntimeException failure){error=failure.getMessage()==null?"This setting could not be saved.":failure.getMessage();render();}}
}
